// Package auth identifies agents by API key.
//
// Keys are 32 random bytes generated by the gateway, so the config stores
// only their SHA-256. A slow password hash (bcrypt, Argon2) exists to stop
// brute-forcing short human passwords; a 256-bit random key cannot be
// brute-forced either way, and a fast hash keeps every request cheap.
package auth

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"strings"
)

// KeyPrefix starts every key. It makes keys easy to recognize, and lets
// secret scanners find one that was committed by mistake.
const KeyPrefix = "mcpgw_"

const keyBytes = 32

// keyLength is the prefix plus 32 bytes in unpadded base64url.
var keyLength = len(KeyPrefix) + base64.RawURLEncoding.EncodedLen(keyBytes)

var (
	// ErrNoKey means the request carried no key.
	ErrNoKey = errors.New("auth: no API key")
	// ErrInvalidKey means the key is malformed or belongs to no agent.
	ErrInvalidKey = errors.New("auth: invalid API key")
)

// Agent is an authenticated caller.
type Agent struct {
	Name string
}

// Entry is one configured agent: its name and the SHA-256 of its key.
type Entry struct {
	Name      string
	KeySHA256 string // 64 lowercase hex characters
}

// GenerateKey returns a new random key.
func GenerateKey() (string, error) {
	b := make([]byte, keyBytes)
	if _, err := rand.Read(b); err != nil {
		return "", fmt.Errorf("auth: generate key: %w", err)
	}
	return KeyPrefix + base64.RawURLEncoding.EncodeToString(b), nil
}

// HashKey returns the SHA-256 of key as lowercase hex, the form stored in
// the config.
func HashKey(key string) string {
	sum := sha256.Sum256([]byte(key))
	return hex.EncodeToString(sum[:])
}

// Authenticator maps keys to agents. It is safe for concurrent use, since
// it is never changed after New.
type Authenticator struct {
	byHash map[[sha256.Size]byte]Agent
}

// New builds an Authenticator. Every entry needs a name and a valid hash,
// and no two entries may share a name or a key.
func New(entries []Entry) (*Authenticator, error) {
	if len(entries) == 0 {
		return nil, errors.New("auth: no agents configured")
	}
	a := &Authenticator{byHash: make(map[[sha256.Size]byte]Agent, len(entries))}
	names := make(map[string]bool, len(entries))
	for _, e := range entries {
		if e.Name == "" {
			return nil, errors.New("auth: agent with empty name")
		}
		if names[e.Name] {
			return nil, fmt.Errorf("auth: duplicate agent name %q", e.Name)
		}
		names[e.Name] = true

		hash, err := parseHash(e.KeySHA256)
		if err != nil {
			return nil, fmt.Errorf("auth: agent %q: %w", e.Name, err)
		}
		if other, dup := a.byHash[hash]; dup {
			return nil, fmt.Errorf("auth: agents %q and %q have the same key", other.Name, e.Name)
		}
		a.byHash[hash] = Agent{Name: e.Name}
	}
	return a, nil
}

func parseHash(s string) ([sha256.Size]byte, error) {
	var hash [sha256.Size]byte
	if len(s) != hex.EncodedLen(sha256.Size) || strings.ToLower(s) != s {
		return hash, errors.New("key_sha256 must be 64 lowercase hex characters (use `gateway keygen`)")
	}
	if _, err := hex.Decode(hash[:], []byte(s)); err != nil {
		return hash, errors.New("key_sha256 must be 64 lowercase hex characters (use `gateway keygen`)")
	}
	return hash, nil
}

// Authenticate returns the agent that owns key. Errors never include the
// key or its hash, so they are safe to log.
//
// The lookup is by the key's SHA-256. A timing difference in the map lookup
// could at most hint at the hash of a guess, which does not help find a key
// that matches a stored hash.
func (a *Authenticator) Authenticate(key string) (Agent, error) {
	if key == "" {
		return Agent{}, ErrNoKey
	}
	if len(key) != keyLength || !strings.HasPrefix(key, KeyPrefix) {
		return Agent{}, ErrInvalidKey
	}
	agent, ok := a.byHash[sha256.Sum256([]byte(key))]
	if !ok {
		return Agent{}, ErrInvalidKey
	}
	return agent, nil
}

// ParseBearer returns the token from an "Authorization: Bearer <token>"
// header value. The scheme is case-insensitive (RFC 9110); the token is not.
func ParseBearer(header string) (string, bool) {
	scheme, token, found := strings.Cut(header, " ")
	if !found || !strings.EqualFold(scheme, "Bearer") || token == "" || strings.ContainsAny(token, " \t") {
		return "", false
	}
	return token, true
}

type agentKey struct{}

// WithAgent returns a context that carries agent.
func WithAgent(ctx context.Context, agent Agent) context.Context {
	return context.WithValue(ctx, agentKey{}, agent)
}

// FromContext returns the agent carried by ctx, if any.
func FromContext(ctx context.Context) (Agent, bool) {
	agent, ok := ctx.Value(agentKey{}).(Agent)
	return agent, ok
}
